  /** Resultado medido (solo si type === 'execution'). */
  execution?: RouterEventExecution;

  /** Origen del evento. */
  source: RouterEventSource;
  /** true si los datos son sintéticos (benchmark, simulación, CLI placeholder). */
  synthetic?: boolean;
}

